class Solution {
public:
    vector<int> minimumTime(int n, vector<vector<int>>& edges, vector<int>& disappear) {
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }

        vector<int> dist(n, INT_MAX);
        dist[0] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        pq.push({0, 0});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;

            for (const auto& [v, len] : adj[u]) {
                int nxt_d = d + len;
                if (nxt_d < disappear[v] && nxt_d < dist[v]) {
                    dist[v] = nxt_d;
                    pq.push({nxt_d, v});
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            if (dist[i] == INT_MAX) dist[i] = -1;
        }
        return dist;
    }
};

class Solution {
    public int[] minimumTime(int n, int[][] edges, int[] disappear) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }

        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1];
            if (d > dist[u]) continue;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], len = edge[1];
                int nxtD = d + len;
                if (nxtD < disappear[v] && nxtD < dist[v]) {
                    dist[v] = nxtD;
                    pq.offer(new int[]{nxtD, v});
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (dist[i] == Integer.MAX_VALUE) dist[i] = -1;
        }
        return dist;
    }
}

var minimumTime = function(n, edges, disappear) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, len] of edges) {
        adj[u].push([v, len]);
        adj[v].push([u, len]);
    }

    const dist = new Array(n).fill(Infinity);
    dist[0] = 0;

    // Binary min-heap
    const heap = [[0, 0]];
    function push(val) {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            let p = Math.floor((idx - 1) / 2);
            if (heap[idx][0] < heap[p][0]) {
                [heap[idx], heap[p]] = [heap[p], heap[idx]];
                idx = p;
            } else break;
        }
    }
    function pop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < heap.length && heap[left][0] < heap[best][0]) best = left;
                if (right < heap.length && heap[right][0] < heap[best][0]) best = right;
                if (best !== idx) {
                    [heap[best], heap[idx]] = [heap[idx], heap[best]];
                    idx = best;
                } else break;
            }
        }
        return top;
    }

    while (heap.length > 0) {
        const [d, u] = pop();
        if (d > dist[u]) continue;

        for (const [v, len] of adj[u]) {
            const nxtD = d + len;
            if (nxtD < disappear[v] && nxtD < dist[v]) {
                dist[v] = nxtD;
                push([nxtD, v]);
            }
        }
    }

    return dist.map(d => d === Infinity ? -1 : d);
};
